    def _resolve_path(obj, path: str):
        cur = obj
        if path is None or path == "":
            return cur
        parts = path.split(".")
        for part in parts:
            if part == "":
                raise KeyError(path)

            token = part
            while True:
                if "[" in token:
                    key, rest = token.split("[", 1)
                    if key:
                        if not isinstance(cur, dict) or key not in cur:
                            raise KeyError(path)
                        cur = cur[key]
                    idx_str, remainder = rest.split("]", 1)
                    if idx_str.strip() == "":
                        raise KeyError(path)
                    try:
                        idx = int(idx_str)
                    except ValueError:
                        raise KeyError(path)
                    if not isinstance(cur, (list, tuple)):
                        raise KeyError(path)
                    try:
                        cur = cur[idx]
                    except IndexError:
                        raise KeyError(path)
                    token = remainder
                    if token == "":
                        break
                    if token[0] != "[":
                        raise KeyError(path)
                    token = token[1:]
                    token = "[" + token
                else:
                    if token.isdigit() and isinstance(cur, (list, tuple)):
                        i = int(token)
                        try:
                            cur = cur[i]
                        except IndexError:
                            raise KeyError(path)
                    else:
                        if not isinstance(cur, dict) or token not in cur:
                            raise KeyError(path)
                        cur = cur[token]
                    break
        return cur

    try:
        extracted = _resolve_path(data, data_key)
    except (KeyError, IndexError, TypeError, ValueError):
        raise KeyError(data_key)

    if extracted is None:
        original = pd.Series([], dtype="float64")
    elif isinstance(extracted, pd.Series):
        original = extracted.astype("float64")
    elif isinstance(extracted, (list, tuple)):
        original = pd.Series(list(extracted), dtype="float64")
    else:
        original = pd.Series([extracted], dtype="float64")

    if original.empty:
        return original.astype("float64"), None, None

    scaler = MinMaxScaler()
    scaled = scaler.fit_transform(original.to_numpy(dtype="float64").reshape(-1, 1)).reshape(-1)
    normalized = pd.Series(scaled, dtype="float64")

    fig, ax = plt.subplots()
    ax.plot(original.index, original.to_numpy(dtype="float64"), label="Original Data")
    ax.plot(normalized.index, normalized.to_numpy(dtype="float64"), label="Normalized Data")
    ax.set_title("Comparison of Original and Normalized Data")
    ax.set_xlabel("Index")
    ax.set_ylabel("Value")
    ax.legend()

    return original.astype("float64"), normalized.astype("float64"), ax
