import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except Exception:
        data = None

    email_re = re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b')

    def replace_emails(obj):
        if isinstance(obj, str):
            return email_re.sub(REPLACE_NONE, obj)
        if isinstance(obj, list):
            return [replace_emails(x) for x in obj]
        if isinstance(obj, dict):
            return {k: replace_emails(v) for k, v in obj.items()}
        return obj

    replaced = replace_emails(data)

    def collect_values(obj, out):
        if obj is None:
            return
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v, out)
            return
        if isinstance(obj, list):
            for x in obj:
                collect_values(x, out)
            return
        out.append(obj)

    values = []
    collect_values(replaced, values)
    value_counts = Counter(values)

    def remove_nones(obj):
        if obj is None:
            return None
        if isinstance(obj, list):
            cleaned = []
            for x in obj:
                cx = remove_nones(x)
                if cx is not None:
                    cleaned.append(cx)
            return cleaned
        if isinstance(obj, dict):
            cleaned = {}
            for k, v in obj.items():
                cv = remove_nones(v)
                if cv is not None:
                    cleaned[k] = cv
            return cleaned
        return obj

    processed = remove_nones(replaced)
    return {"data": processed, "value_counts": value_counts}
